import json
from pathlib import Path

root = Path(__file__).resolve().parents[1]
config = json.loads((root / 'account-routing-defaults.json').read_text())
target = root / 'backend/internal/pkg/accountbalance/defaults_gen.go'
target.parent.mkdir(parents=True, exist_ok=True)
target.write_text(
    '// Code generated by tools/generate_account_routing_defaults.py; DO NOT EDIT.\n'
    'package accountbalance\n\n'
    f'const QuotaGapPercent = {config["quota_gap_percent"]}\n'
    f'const QuotaSnapshotMaxAgeSeconds = {config["quota_snapshot_max_age_seconds"]}\n'
)
